CREATE TABLE IF NOT EXISTS teachers(id INTEGER PRIMARY KEY AUTOINCREMENT,email TEXT UNIQUE NOT NULL,salt TEXT NOT NULL,pass TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS exams(id TEXT PRIMARY KEY,code TEXT UNIQUE NOT NULL,teacher_id INTEGER NOT NULL,title TEXT NOT NULL,minutes INTEGER NOT NULL,shuffle INTEGER DEFAULT 0,data TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS submissions(id INTEGER PRIMARY KEY AUTOINCREMENT,exam_id TEXT NOT NULL,name TEXT NOT NULL,score REAL NOT NULL,correct INTEGER NOT NULL,total INTEGER NOT NULL,answers TEXT NOT NULL,created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_sub_exam ON submissions(exam_id);
